import React from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Animated, useWindowDimensions } from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';
import { useNavigation } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';

import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import Feather from 'react-native-vector-icons/Feather';

import SplashLogoScreen from '../screens/SplashLogoScreen';
import TelaInicio from '../screens/Inicio';
import TelaCriarEscala from '../screens/TelaCriarEscala';
import TelaListaEscalas from '../screens/TelaListaEscalas';
import TelaDetalhesEscala from '../screens/DetalhesEscala';
import RepertoiresScreen from '../screens/Repertorios';
import AdicionarRepertorio from '../screens/AdicionarRepertorio';
import DetalheRepertorio from '../screens/DetalheRepertorio';
import VisualizarArquivo from '../screens/VisualizarArquivo';
import PresencaScreen from '../screens/Presenca';
import AvisosScreen from '../screens/Avisos';
import EnsaiosScreen from '../screens/Ensaios';
import TelaAniversariantes from '../screens/Aniversariantes';
import TelaAgenda from '../screens/Agenda';
import InteracaoScreen from '../screens/Interacao';

const Stack = createStackNavigator();
const GRADIENTE_BARRA = ['#243248', '#111722', '#000000'];
const COR_ICONE_INATIVO = '#F8FBFF';
const COR_ICONE_ATIVO = '#050505';

const neuMorphShadow = {
  shadowColor: '#000',
  shadowOffset: { width: 0, height: 12 },
  shadowOpacity: 0.38,
  shadowRadius: 22,
  elevation: 18,
};

const BarraNavegacaoFixa = () => {
  const navegacao = useNavigation();
  const { width } = useWindowDimensions();
  const obterRotaAtual = React.useCallback(() => {
    const estadoNavegacao = navegacao.getState();
    return estadoNavegacao?.routes[estadoNavegacao.index]?.name || 'Inicio';
  }, [navegacao]);

  const [rotaAtual, setRotaAtual] = React.useState(obterRotaAtual);

  const itens = React.useMemo(() => [
    { biblioteca: 'materialCommunity', nome: 'bell-ring-outline', nomeAtivo: 'bell-ring', rota: 'Avisos', texto: 'Avisos' },
    { biblioteca: 'materialCommunity', nome: 'music-box-multiple-outline', nomeAtivo: 'music-box-multiple', rota: 'Repertorios', texto: 'Repertórios', rotasAtivas: ['Repertorios', 'AdicionarRepertorio', 'DetalheRepertorio', 'VisualizarArquivo'] },
    { biblioteca: 'material', nome: 'event', nomeAtivo: 'event-available', rota: 'Escalas', texto: 'Escalas', rotasAtivas: ['Escalas', 'DetalhesEscala'] },
    { biblioteca: 'feather', bibliotecaAtiva: 'materialCommunity', nome: 'plus', nomeAtivo: 'plus-circle', rota: 'CriarEscala', texto: 'Criar' },
    { biblioteca: 'materialCommunity', nome: 'home-outline', nomeAtivo: 'home', rota: 'Inicio', texto: 'Inicio' },
    { biblioteca: 'feather', bibliotecaAtiva: 'materialCommunity', nome: 'user-check', nomeAtivo: 'account-check', rota: 'Presenca', texto: 'Presenca' },
    { biblioteca: 'materialCommunity', nome: 'book-open-page-variant-outline', nomeAtivo: 'book-open-page-variant', rota: 'Ensaios', texto: 'Devocional' },
    { biblioteca: 'materialCommunity', nome: 'gift-outline', nomeAtivo: 'gift', rota: 'Aniversariantes', texto: 'Aniversariantes' },
    { biblioteca: 'materialCommunity', nome: 'calendar-month-outline', nomeAtivo: 'calendar-month', rota: 'Agenda', texto: 'Agenda' },
  ], []);

  const animEscala = React.useRef(
    Array(itens.length).fill(0).map(() => new Animated.Value(1))
  ).current;
  const animToque = React.useRef(
    Array(itens.length).fill(0).map(() => new Animated.Value(0))
  ).current;
  const animBrilho = React.useRef(new Animated.Value(0)).current;
  const loopsItens = React.useRef<(Animated.CompositeAnimation | null)[]>(
    Array(itens.length).fill(null)
  ).current;

  React.useEffect(() => {
    setRotaAtual(obterRotaAtual());
    const unsubscribe = navegacao.addListener('state', () => {
      setRotaAtual(obterRotaAtual());
    });

    return unsubscribe;
  }, [navegacao, obterRotaAtual]);

  React.useEffect(() => {
    const animacaoBrilho = Animated.loop(
      Animated.sequence([
        Animated.timing(animBrilho, {
          toValue: 1,
          duration: 7600,
          useNativeDriver: true,
        }),
        Animated.timing(animBrilho, {
          toValue: 0,
          duration: 7600,
          useNativeDriver: true,
        }),
      ])
    );

    animacaoBrilho.start();

    return () => animacaoBrilho.stop();
  }, [animBrilho]);

  React.useEffect(() => {
    itens.forEach((item, indice) => {
      const selecionado = item.rota === rotaAtual || item.rotasAtivas?.includes(rotaAtual);
      loopsItens[indice]?.stop();
      loopsItens[indice] = null;
      animEscala[indice].stopAnimation();
      animToque[indice].stopAnimation();

      if (selecionado) {
        Animated.spring(animToque[indice], {
          toValue: 1,
          friction: 7,
          tension: 95,
          useNativeDriver: true,
        }).start();

        const loopAtivo = Animated.loop(
          Animated.sequence([
            Animated.timing(animEscala[indice], {
              toValue: 1.045,
              duration: 1100,
              useNativeDriver: true,
            }),
            Animated.timing(animEscala[indice], {
              toValue: 1.015,
              duration: 1100,
              useNativeDriver: true,
            }),
          ])
        );

        loopsItens[indice] = loopAtivo;
        loopAtivo.start();
        return;
      }

      Animated.spring(animEscala[indice], {
        toValue: 1,
        friction: 8,
        tension: 50,
        useNativeDriver: true,
      }).start();
      Animated.spring(animToque[indice], {
        toValue: 0,
        friction: 8,
        tension: 60,
        useNativeDriver: true,
      }).start();
    });

    return () => {
      loopsItens.forEach((loop) => loop?.stop());
    };
  }, [rotaAtual, itens, animEscala, animToque, loopsItens]);

  if (rotaAtual === 'SplashLogo') return null;

  const larguraItem = Math.max(34, Math.min(44, (width - 18) / itens.length));
  const tamanhoIconePadrao = width < 370 ? 20 : 22;
  const tamanhoIconeAcao = width < 370 ? 21 : 23;

  return (
    <LinearGradient
      colors={GRADIENTE_BARRA}
      start={{ x: 0, y: 0 }}
      end={{ x: 0, y: 1 }}
      style={estilos.barraNavegacao}
    >
      <Animated.View
        pointerEvents="none"
        style={[
          estilos.reflexoBarra,
          {
            opacity: animBrilho.interpolate({
              inputRange: [0, 0.5, 1],
              outputRange: [0.08, 0.24, 0.08],
            }),
            transform: [{
              translateX: animBrilho.interpolate({
                inputRange: [0, 1],
                outputRange: [-140, width + 40],
              }),
            }],
          },
        ]}
      />
      <View style={estilos.conteudoBarra}>
        {itens.map((item, indice) => {
          const selecionado = item.rota === rotaAtual || item.rotasAtivas?.includes(rotaAtual);
          const corIcone = selecionado ? COR_ICONE_ATIVO : COR_ICONE_INATIVO;
          const bibliotecaIcone = selecionado && item.bibliotecaAtiva ? item.bibliotecaAtiva : item.biblioteca;
          const nomeIcone = selecionado ? item.nomeAtivo : item.nome;
          const tamanho = nomeIcone === 'plus' || nomeIcone === 'plus-circle' ? tamanhoIconeAcao : tamanhoIconePadrao;
          const deslocamentoAtivo = animToque[indice].interpolate({
            inputRange: [0, 1],
            outputRange: [0, -22],
          });

          const navegarComAnimacao = () => {
            Animated.sequence([
              Animated.spring(animEscala[indice], {
                toValue: 0.9,
                friction: 5,
                tension: 130,
                useNativeDriver: true,
              }),
              Animated.spring(animEscala[indice], {
                toValue: selecionado ? 1.1 : 1.04,
                friction: 5,
                tension: 120,
                useNativeDriver: true,
              }),
            ]).start();

            navegacao.navigate(item.rota as never);
          };

          return (
            <TouchableOpacity
              key={item.rota}
              style={[estilos.itemBarra, { width: larguraItem }]}
              activeOpacity={0.85}
              accessibilityLabel={item.texto}
              onPress={navegarComAnimacao}
            >
              <Animated.View
                style={[
                  estilos.itemAnimado,
                  {
                    transform: [
                      { scale: animEscala[indice] },
                      { translateY: deslocamentoAtivo },
                    ],
                  },
                ]}
              >
                {selecionado && (
                  <Animated.View
                    pointerEvents="none"
                    style={[
                      estilos.anelNeonAtivo,
                      {
                        opacity: animEscala[indice].interpolate({
                          inputRange: [1.03, 1.1],
                          outputRange: [0.35, 0.78],
                        }),
                        transform: [{
                          scale: animEscala[indice].interpolate({
                            inputRange: [1.03, 1.1],
                            outputRange: [0.94, 1.14],
                          }),
                        }],
                      },
                    ]}
                  />
                )}
                <View style={[
                  estilos.containerIconeBase,
                  !selecionado && estilos.iconeInativoGlow,
                  selecionado && estilos.itemAtivo,
                ]}>
                  {bibliotecaIcone === 'materialCommunity' && (
                    <MaterialCommunityIcons name={nomeIcone} size={tamanho} color={corIcone} />
                  )}
                  {bibliotecaIcone === 'material' && (
                    <MaterialIcons name={nomeIcone} size={tamanho} color={corIcone} />
                  )}
                  {bibliotecaIcone === 'feather' && (
                    <Feather name={nomeIcone} size={tamanho} color={corIcone} />
                  )}
                </View>
                {selecionado && (
                  <Text style={estilos.labelItemAtivo}>
                    {item.texto}
                  </Text>
                )}
              </Animated.View>
            </TouchableOpacity>
          );
        })}
      </View>
    </LinearGradient>
  );
};

export default function AppNavigator() {
  return (
    <View style={estilos.containerPrincipal}>
      <View style={estilos.areaConteudo}>
        <Stack.Navigator initialRouteName="SplashLogo" screenOptions={{ headerShown: false }}>
          <Stack.Screen name="SplashLogo" component={SplashLogoScreen} />
          <Stack.Screen name="Inicio" component={TelaInicio} />
          <Stack.Screen name="CriarEscala" component={TelaCriarEscala} />
          <Stack.Screen name="Escalas" component={TelaListaEscalas} />
          <Stack.Screen name="DetalhesEscala" component={TelaDetalhesEscala} />
          <Stack.Screen name="Repertorios" component={RepertoiresScreen} />
          <Stack.Screen name="AdicionarRepertorio" component={AdicionarRepertorio} />
          <Stack.Screen name="DetalheRepertorio" component={DetalheRepertorio} />
          <Stack.Screen name="VisualizarArquivo" component={VisualizarArquivo} />
          <Stack.Screen name="Presenca" component={PresencaScreen} />
          <Stack.Screen name="Avisos" component={AvisosScreen} />
          <Stack.Screen name="Ensaios" component={EnsaiosScreen} />
          <Stack.Screen name="Aniversariantes" component={TelaAniversariantes} />
          <Stack.Screen name="Interacao" component={InteracaoScreen} />
          <Stack.Screen name="Agenda" component={TelaAgenda} />
        </Stack.Navigator>
      </View>
      <BarraNavegacaoFixa />
    </View>
  );
}

const estilos = StyleSheet.create({
  containerPrincipal: {
    flex: 1,
    position: 'relative',
    backgroundColor: '#121212ea',
  },
  areaConteudo: {
    flex: 1,
    paddingBottom: 84,
  },
  barraNavegacao: {
    position: 'absolute',
    bottom: 7,
    left: 5,
    right: 5,
    height: 68,
    borderRadius: 10,
    overflow: 'visible',
    borderWidth: 1,
    borderTopColor: 'rgba(103,232,249,0.65)',
    borderLeftColor: 'rgba(103,232,249,0.45)',
    borderRightColor: 'rgba(103,232,249,0.45)',
    borderBottomColor: 'rgba(103,232,249,0.65)',
    ...neuMorphShadow,
  },
  reflexoBarra: {
    position: 'absolute',
    top: -10,
    bottom: -10,
    width: 70,
    backgroundColor: 'rgba(103,232,249,0.1)',
    borderRadius: 35,
    transform: [{ rotate: '14deg' }],
  },
  conteudoBarra: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 2,
    paddingTop: 12,
    paddingBottom: 4,
    overflow: 'visible',
  },
  itemBarra: {
    alignItems: 'center',
    justifyContent: 'center',
    height: 56,
    overflow: 'visible',
  },
  itemAnimado: {
    width: 42,
    height: 54,
    justifyContent: 'center',
    alignItems: 'center',
    position: 'relative',
    overflow: 'visible',
  },
  containerIconeBase: {
    width: 34,
    height: 34,
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 17,
    position: 'relative',
    zIndex: 3,
  },
  itemAtivo: {
    width: 48,
    height: 48,
    borderRadius: 24,
    backgroundColor: '#FFFFFF',
    borderWidth: 3,
    borderColor: 'rgba(103,232,249,0.9)',
    shadowColor: '#67E8F9',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.9,
    shadowRadius: 12,
    elevation: 12,
  },
  anelNeonAtivo: {
    position: 'absolute',
    width: 56,
    height: 56,
    borderRadius: 28,
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.95)',
    backgroundColor: 'rgba(255,255,255,0.2)',
    zIndex: 2,
    shadowColor: '#67E8F9',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.55,
    shadowRadius: 12,
  },
  iconeInativoGlow: {
    shadowColor: '#FFFFFF',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.18,
    shadowRadius: 6,
    elevation: 3,
  },
  labelItemAtivo: {
    position: 'absolute',
    top: -27,
    color: '#F8FBFF',
    fontSize: 8,
    lineHeight: 9,
    fontWeight: '800',
    minWidth: 0,
    maxWidth: 96,
    textAlign: 'center',
    textShadowColor: 'rgba(103,232,249,0.85)',
    textShadowOffset: { width: 0, height: 0 },
    textShadowRadius: 5,
    backgroundColor: 'rgba(0,0,0,0.74)',
    borderRadius: 8,
    paddingHorizontal: 3,
    paddingVertical: 3,
    overflow: 'hidden',
    zIndex: 6,
  },
});
