import React, { useState } from 'react';
import {
  TextInput,
  TouchableOpacity,
  Text,
  Alert,
  ActivityIndicator,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  View,
  Animated,
} from 'react-native';
import { sendPasswordResetEmail, signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../services/firebaseConfig';
import { getFirestore, doc, getDoc } from 'firebase/firestore';
import { LinearGradient } from 'expo-linear-gradient';

const db = getFirestore();

function NeumorphicField({ children, style }: any) {
  return (
    <View style={[estilos.neumorphicOuter, style]}>
      <LinearGradient
        colors={['rgba(255,255,255,0.13)', 'rgba(255,255,255,0.04)']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={estilos.neumorphicInner}
      >
        {children}
      </LinearGradient>
    </View>
  );
}

function NeumorphicButton({ children, onPress, style }: any) {
  const scale = React.useRef(new Animated.Value(1)).current;

  const handlePressIn = () => {
    Animated.spring(scale, {
      toValue: 0.97,
      useNativeDriver: true,
      speed: 50,
      bounciness: 0,
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scale, {
      toValue: 1,
      useNativeDriver: true,
      speed: 50,
      bounciness: 8,
    }).start();
  };

  return (
    <TouchableOpacity
      activeOpacity={0.85}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      onPress={onPress}
      style={{ width: '100%' }}
    >
      <Animated.View
        style={[
          {
            transform: [{ scale }],
          },
          estilos.neumorphicOuter,
          style,
        ]}
      >
        <LinearGradient
          colors={['#ffb545', '#ff7a18', '#f24b8f']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={estilos.botaoGradiente}
        >
          {children}
        </LinearGradient>
      </Animated.View>
    </TouchableOpacity>
  );
}

export default function TelaLogin({ navigation }: any): JSX.Element {
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [carregando, setCarregando] = useState(false);
  const [enviandoReset, setEnviandoReset] = useState(false);

  const fazerLogin = async () => {
    if (!email || !senha) {
      Alert.alert('Erro', 'Preencha email e senha!');
      return;
    }

    setCarregando(true);

    try {
      const credenciais = await signInWithEmailAndPassword(auth, email, senha);
      const usuário = credenciais.user;

      if (!usuário.emailVerified) {
        Alert.alert(
          'Email não verificado',
          'Por favor, confirme seu email antes de fazer login.'
        );
        await auth.signOut();
        setCarregando(false);
        return;
      }

      // Verifica se o usuário existe no Firestore (ID = uid)
      const usuárioRef = doc(db, 'usuários', usuário.uid);
      const usuárioSnap = await getDoc(usuárioRef);

      if (!usuárioSnap.exists()) {
        Alert.alert(
          'Usuário não cadastrado',
          'Seu usuário não foi encontrado no banco de dados. Faça o cadastro primeiro.'
        );
        await auth.signOut();
        setCarregando(false);
        return;
      }

      navigation.replace('SplashLogo', { destino: 'Inicio' });

    } catch (erro: any) {
      let mensagem = 'Erro ao fazer login. Tente novamente.';

      if (erro.code) {
        switch (erro.code) {
          case 'auth/user-not-found':
            mensagem = 'Usuário não encontrado.';
            break;
          case 'auth/wrong-password':
            mensagem = 'Senha incorreta.';
            break;
          case 'auth/invalid-email':
            mensagem = 'Email inválido.';
            break;
          default:
            mensagem = erro.message || mensagem;
        }
      }

      Alert.alert('Erro', mensagem);
    } finally {
      setCarregando(false);
    }
  };

  const enviarRedefinicaoSenha = async () => {
    const emailLimpo = email.trim();

    if (!emailLimpo) {
      Alert.alert('Informe seu email', 'Digite seu email no campo acima para receber o link de redefinicao de senha.');
      return;
    }

    setEnviandoReset(true);

    try {
      await sendPasswordResetEmail(auth, emailLimpo);
      Alert.alert(
        'Link enviado',
        'Enviamos um link para seu email. Abra a mensagem e siga as instrucoes para criar uma nova senha.'
      );
    } catch (erro: any) {
      let mensagem = 'Não foi possível enviar o link agora. Tente novamente.';

      if (erro.code === 'auth/invalid-email') {
        mensagem = 'Digite um email valido para receber o link.';
      } else if (erro.code === 'auth/user-not-found') {
        mensagem = 'Não encontramos uma conta com este email.';
      }

      Alert.alert('Erro', mensagem);
    } finally {
      setEnviandoReset(false);
    }
  };

  return (
    <KeyboardAvoidingView
      style={estilos.tela}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <LinearGradient
        colors={['#100f2e', '#191339', '#0f213f', '#111827']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={estilos.fundo}
      >
        <View style={estilos.luzTopo} />
        <View style={estilos.luzBaixo} />
        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={estilos.container}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
          bounces={false}
          overScrollMode="never"
        >
          <View style={estilos.cartao}>
            <View style={estilos.marcaWrap}>
              <LinearGradient
                colors={['#ffb545', '#f24b8f']}
                style={estilos.marca}
              >
                <Text style={estilos.marcaTexto}>S</Text>
              </LinearGradient>
            </View>

            <Text style={estilos.titulo}>Login</Text>
            <Text style={estilos.subtitulo}>Entre e acesse o conteúdo do aplicativo.</Text>

            <NeumorphicField style={{ marginBottom: 16 }}>
              <TextInput
                placeholder="Email"
                value={email}
                onChangeText={setEmail}
                keyboardType="email-address"
                autoCapitalize="none"
                style={estilos.entrada}
                placeholderTextColor="#b8bfd6"
                editable={!carregando}
              />
            </NeumorphicField>

            <NeumorphicField style={{ marginBottom: 12 }}>
              <TextInput
                placeholder="Senha"
                value={senha}
                onChangeText={setSenha}
                secureTextEntry
                style={estilos.entrada}
                placeholderTextColor="#b8bfd6"
                editable={!carregando}
              />
            </NeumorphicField>

            <TouchableOpacity
              onPress={enviarRedefinicaoSenha}
              disabled={carregando || enviandoReset}
              style={estilos.esqueciSenhaBotao}
            >
              <Text style={[estilos.textoEsqueciSenha, (carregando || enviandoReset) && estilos.textoDesabilitado]}>
                {enviandoReset ? 'Enviando link...' : 'Esqueci minha senha'}
              </Text>
            </TouchableOpacity>

            {carregando ? (
              <ActivityIndicator
                size="large"
                color="#ffb545"
                style={{ marginVertical: 12 }}
              />
            ) : (
              <NeumorphicButton style={estilos.botao} onPress={fazerLogin}>
                <Text style={estilos.textoBotao}>Entrar</Text>
              </NeumorphicButton>
            )}

            <TouchableOpacity
              onPress={() => navigation.navigate('Cadastro')}
              disabled={carregando}
            >
              <Text style={estilos.textoCadastro}>
                Não tem conta? Cadastre-se
              </Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
      </LinearGradient>
    </KeyboardAvoidingView>
  );
}

